</head>
<body>

  <header>
    <h1>🎱 2D Billiards Simulation</h1>
  </header>

  <div class="instructions">
    <strong>How to Shoot:</strong> Click and hold on the <strong>white cue ball</strong>, drag <strong>backwards</strong> to set aim line and power, then <strong>release</strong> to strike! Longer drag = harder shot.
  </div>

  <div class="controls">
    <button id="rack-btn">Reset / Rack</button>
    <div id="status-badge" class="status-badge">Ready</div>
  </div>

  <div class="table-container">
    <canvas id="canvas" width="800" height="400"></canvas>
  </div>

  <div class="potted-tray">
    <div class="potted-label">Potted:</div>
    <div id="potted-list" class="potted-list"></div>
  </div>

  <script>
    (function () {
      const W = 800;
      const H = 400;
      const R = 12;
      const PR = 22; // Pocket radius
      const PR_SQ = PR * PR;

      const CUSHION_RESTITUTION = 0.98;
      const BALL_RESTITUTION = 0.99;
      const FRICTION = 110; // px/sec^2 deceleration

      const pockets = [
        { x: 0, y: 0 },
        { x: W / 2, y: 0 },
        { x: W, y: 0 },
        { x: 0, y: H },
        { x: W / 2, y: H },
        { x: W, y: H }
      ];

      const ballColors = [
        '#ffffff', // 0: Cue
        '#f1c40f', // 1: Yellow
        '#2980b9', // 2: Blue
        '#e74c3c', // 3: Red
        '#8e44ad', // 4: Purple
        '#e67e22', // 5: Orange
        '#27ae60', // 6: Green
        '#78281f', // 7: Maroon
        '#111111', // 8: Black
        '#f1c40f', // 9: Yellow stripe
        '#2980b9', // 10: Blue stripe
        '#e74c3c', // 11: Red stripe
        '#8e44ad', // 12: Purple stripe
        '#e67e22', // 13: Orange stripe
        '#27ae60', // 14: Green stripe
        '#78281f'  // 15: Maroon stripe
      ];

      let simBalls = [];
      let isDragging = false;
      let dragPos = { x: 0, y: 0 };
      let animId = null;
      let isRunning = false;
      let lastTimestamp = null;

      const canvas = document.getElementById('canvas');
      const ctx = canvas.getContext('2d');
      const rackBtn = document.getElementById('rack-btn');
      const statusBadge = document.getElementById('status-badge');
      const pottedList = document.getElementById('potted-list');

      function createStandardRack() {
        const balls = [];
        // Cue ball
        balls.push({
          x: W * 0.25,
          y: H * 0.5,
          vx: 0,
          vy: 0,
          cue: true,
          num: 0,
          color: '#ffffff',
          isStripe: false
        });

        const rackOrder = [1, 2, 9, 3, 8, 10, 4, 11, 5, 12, 6, 13, 7, 14, 15];
        const startX = W * 0.68;
        const startY = H * 0.5;
        const dx = R * 1.732 + 0.4; // triangle row spacing
        const dy = R * 2.0 + 0.4;   // ball spacing

        let orderIdx = 0;
        for (let row = 0; row < 5; row++) {
          const count = row + 1;
          const rowX = startX + row * dx;
          const rowStartY = startY - (row * dy) / 2;

          for (let col = 0; col < count; col++) {
            const num = rackOrder[orderIdx++];
            const rowY = rowStartY + col * dy;
            balls.push({
              x: rowX,
              y: rowY,
              vx: 0,
              vy: 0,
              cue: false,
              num: num,
              color: ballColors[num] || '#cccccc',
              isStripe: num > 8
            });
          }
        }
        return balls;
      }

      function getDefaultColor(idx, cue) {
        if (cue) return '#ffffff';
        const num = (idx % 15) + 1;
        return ballColors[num] || '#e74c3c';
      }

      // Web Audio sound synth
      function playHitSound(vol = 0.5) {
        try {
          const AudioCtx = window.AudioContext || window.webkitAudioContext;
          if (!AudioCtx) return;
          if (!window._audioCtx) window._audioCtx = new AudioCtx();
          if (window._audioCtx.state === 'suspended') window._audioCtx.resume();

          const ctxA = window._audioCtx;
          const osc = ctxA.createOscillator();
          const gain = ctxA.createGain();
          osc.type = 'triangle';
          osc.frequency.setValueAtTime(300 + Math.random() * 150, ctxA.currentTime);
          osc.frequency.exponentialRampToValueAtTime(60, ctxA.currentTime + 0.04);

          gain.gain.setValueAtTime(Math.min(0.8, vol), ctxA.currentTime);
          gain.gain.exponentialRampToValueAtTime(0.001, ctxA.currentTime + 0.04);

          osc.connect(gain);
          gain.connect(ctxA.destination);
          osc.start();
          osc.stop(ctxA.currentTime + 0.04);
        } catch (e) {}
      }

      // Core simulation step
      function stepPhysics(subDt) {
        const len = simBalls.length;

        // 1. Advance position
        for (let i = 0; i < len; i++) {
          const b = simBalls[i];
          if (b.potted) continue;
          b.x += b.vx * subDt;
          b.y += b.vy * subDt;
        }

        // 2. Check Pockets
        for (let i = 0; i < len; i++) {
          const b = simBalls[i];
          if (b.potted) continue;

          for (let p = 0; p < pockets.length; p++) {
            const pkt = pockets[p];
            const dx = b.x - pkt.x;
            const dy = b.y - pkt.y;
            if (dx * dx + dy * dy <= PR_SQ) {
              b.potted = true;
              b.vx = 0;
              b.vy = 0;
              playHitSound(0.7);
              break;
            }
          }
        }

        // 3. Cushion Bounces
        for (let i = 0; i < len; i++) {
          const b = simBalls[i];
          if (b.potted) continue;

          let bounced = false;
          if (b.x < R) {
            b.x = R;
            if (b.vx < 0) { b.vx = -b.vx * CUSHION_RESTITUTION; bounced = true; }
          } else if (b.x > W - R) {
            b.x = W - R;
            if (b.vx > 0) { b.vx = -b.vx * CUSHION_RESTITUTION; bounced = true; }
          }

          if (b.y < R) {
            b.y = R;
            if (b.vy < 0) { b.vy = -b.vy * CUSHION_RESTITUTION; bounced = true; }
          } else if (b.y > H - R) {
            b.y = H - R;
            if (b.vy > 0) { b.vy = -b.vy * CUSHION_RESTITUTION; bounced = true; }
          }

          if (bounced) {
            playHitSound(0.2);
          }
        }

        // 4. Ball-to-Ball Collisions (2 passes per sub-step for stability)
        const minDist = 2 * R;
        const minDistSq = minDist * minDist;

        for (let pass = 0; pass < 2; pass++) {
          for (let i = 0; i < len; i++) {
            const b1 = simBalls[i];
            if (b1.potted) continue;

            for (let j = i + 1; j < len; j++) {
              const b2 = simBalls[j];
              if (b2.potted) continue;

              const dx = b2.x - b1.x;
              const dy = b2.y - b1.y;
              const distSq = dx * dx + dy * dy;

              if (distSq < minDistSq && distSq > 0.000001) {
                const dist = Math.sqrt(distSq);
                const nx = dx / dist;
                const ny = dy / dist;

                // Positional overlap resolution
                const overlap = minDist - dist;
                const shiftX = nx * overlap * 0.5;
                const shiftY = ny * overlap * 0.5;
                b1.x -= shiftX;
                b1.y -= shiftY;
                b2.x += shiftX;
                b2.y += shiftY;

                // Velocity impulse along normal
                const vxRel = b1.vx - b2.vx;
                const vyRel = b1.vy - b2.vy;
                const vNormal = vxRel * nx + vyRel * ny;

                if (vNormal > 0) {
                  const impulse = (1 + BALL_RESTITUTION) * vNormal * 0.5;
                  b1.vx -= impulse * nx;
                  b1.vy -= impulse * ny;
                  b2.vx += impulse * nx;
                  b2.vy += impulse * ny;
                  playHitSound(Math.min(1.0, vNormal / 400));
                }
              }
            }
          }
        }

        // Position clamping after collision resolution to stay inside felt bounds
        for (let i = 0; i < len; i++) {
          const b = simBalls[i];
          if (b.potted) continue;
          if (b.x < R) b.x = R;
          if (b.x > W - R) b.x = W - R;
          if (b.y < R) b.y = R;
          if (b.y > H - R) b.y = H - R;
        }

        // 5. Friction / Rolling resistance
        for (let i = 0; i < len; i++) {
          const b = simBalls[i];
          if (b.potted) continue;

          const speed = Math.hypot(b.vx, b.vy);
          if (speed > 0) {
            const newSpeed = Math.max(0, speed - FRICTION * subDt);
            if (newSpeed === 0) {
              b.vx = 0;
              b.vy = 0;
            } else {
              const factor = newSpeed / speed;
              b.vx *= factor;
              b.vy *= factor;
            }
          }
        }
      }

      // Global window.sim contract implementation
      window.sim = {
        W: W,
        H: H,
        R: R,

        reset: function (ballsArray) {
          if (!ballsArray || !Array.isArray(ballsArray) || ballsArray.length === 0) {
            ballsArray = createStandardRack();
          }

          simBalls = ballsArray.map((b, idx) => {
            const isCue = !!b.cue;
            return {
              x: Number(b.x),
              y: Number(b.y),
              vx: Number(b.vx || 0),
              vy: Number(b.vy || 0),
              potted: !!b.potted,
              cue: isCue,
              num: b.num !== undefined ? b.num : (isCue ? 0 : idx),
              color: b.color || getDefaultColor(idx, isCue),
              isStripe: b.isStripe !== undefined ? b.isStripe : (b.num > 8)
            };
          });

          isDragging = false;
          redraw();
          updatePottedTray();
        },

        step: function (dt) {
          if (dt <= 0) {
            redraw();
            return;
          }

          const MAX_SUB_DT = 0.0005; // 0.5 ms sub-steps for smooth physics
          const steps = Math.max(1, Math.ceil(dt / MAX_SUB_DT));
          const subDt = dt / steps;

          for (let s = 0; s < steps; s++) {
            stepPhysics(subDt);
          }

          redraw();
          updatePottedTray();
        },

        state: function () {
          return simBalls.map(b => ({
            x: b.x,
            y: b.y,
            vx: b.vx,
            vy: b.vy,
            potted: b.potted,
            cue: b.cue
          }));
        },

        shoot: function (vx, vy) {
          let cb = simBalls.find(b => b.cue);
          if (!cb && simBalls.length > 0) cb = simBalls[0];
          if (cb) {
            if (cb.potted) {
              cb.potted = false;
              cb.x = W * 0.25;
              cb.y = H * 0.5;
            }
            cb.vx = Number(vx);
            cb.vy = Number(vy);
            playHitSound(Math.min(1.0, Math.hypot(vx, vy) / 500));
          }
        },

        pause: function () {
          isRunning = false;
          if (animId !== null) {
            cancelAnimationFrame(animId);
            animId = null;
          }
        },

        resume: function () {
          if (!isRunning) {
            isRunning = true;
            lastTimestamp = null;
            animId = requestAnimationFrame(loop);
          }
        }
      };

      function loop(timestamp) {
        if (!isRunning) return;
        if (lastTimestamp === null) lastTimestamp = timestamp;
        let dt = (timestamp - lastTimestamp) / 1000;
        lastTimestamp = timestamp;

        if (dt > 0.033) dt = 0.033; // Clamp max dt frame gap
        if (dt > 0) {
          window.sim.step(dt);
        }

        animId = requestAnimationFrame(loop);
      }

      function updateStatusBadge() {
        let movingCount = 0;
        for (let b of simBalls) {
          if (!b.potted && (Math.abs(b.vx) > 1 || Math.abs(b.vy) > 1)) {
            movingCount++;
          }
        }

        if (movingCount > 0) {
          statusBadge.textContent = "Balls Moving...";
          statusBadge.style.color = "#f6ad55";
          statusBadge.style.borderColor = "#dd6b20";
        } else {
          statusBadge.textContent = "Ready - Aim & Shoot";
          statusBadge.style.color = "#68d391";
          statusBadge.style.borderColor = "#38a169";
        }
      }

      function updatePottedTray() {
        pottedList.innerHTML = '';
        for (let b of simBalls) {
          if (b.potted && !b.cue) {
            const el = document.createElement('div');
            el.className = 'potted-ball-icon';
            el.style.backgroundColor = b.color || '#fff';
            el.style.color = b.color === '#111111' || b.color === '#2980b9' || b.color === '#78281f' || b.color === '#8e44ad' ? '#fff' : '#000';
            el.textContent = b.num || '';
            pottedList.appendChild(el);
          }
        }
      }

      // Canvas Rendering logic
      function redraw() {
        updateStatusBadge();

        // 1. Felt Background
        ctx.fillStyle = '#0d5c2d';
        ctx.fillRect(0, 0, W, H);

        // Head string line & Foot spot marker
        ctx.strokeStyle = 'rgba(255, 255, 255, 0.15)';
        ctx.lineWidth = 1.5;
        ctx.beginPath();
        ctx.moveTo(W * 0.25, 0);
        ctx.lineTo(W * 0.25, H);
        ctx.stroke();

        ctx.fillStyle = 'rgba(255, 255, 255, 0.2)';
        ctx.beginPath();
        ctx.arc(W * 0.70, H * 0.5, 3, 0, Math.PI * 2);
        ctx.fill();

        // 2. Cushions (Outer 12px strip borders)
        ctx.fillStyle = '#09401f';
        // Top cushion
        ctx.fillRect(0, 0, W, R);
        // Bottom cushion
        ctx.fillRect(0, H - R, W, R);
        // Left cushion
        ctx.fillRect(0, 0, R, H);
        // Right cushion
        ctx.fillRect(W - R, 0, R, H);

        // 3. Pockets
        for (let p of pockets) {
          // Pocket shadow/hole
          const grad = ctx.createRadialGradient(p.x, p.y, 2, p.x, p.y, PR);
          grad.addColorStop(0, '#000000');
          grad.addColorStop(0.8, '#121212');
          grad.addColorStop(1, '#2d3748');

          ctx.fillStyle = grad;
          ctx.beginPath();
          ctx.arc(p.x, p.y, PR, 0, Math.PI * 2);
          ctx.fill();

          // Pocket brass rim border
          ctx.strokeStyle = '#4a3623';
          ctx.lineWidth = 2;
          ctx.stroke();
        }

        // 4. Balls
        for (let b of simBalls) {
          if (b.potted) continue;

          // Shadow
          ctx.fillStyle = 'rgba(0, 0, 0, 0.35)';
          ctx.beginPath();
          ctx.arc(b.x + 2, b.y + 3, R, 0, Math.PI * 2);
          ctx.fill();

          // Ball Body
          ctx.save();
          ctx.beginPath();
          ctx.arc(b.x, b.y, R, 0, Math.PI * 2);
          ctx.clip();

          if (b.isStripe) {
            // White base for stripe
            ctx.fillStyle = '#f8f9fa';
            ctx.fillRect(b.x - R, b.y - R, R * 2, R * 2);

            // Center stripe
            ctx.fillStyle = b.color || '#e74c3c';
            ctx.fillRect(b.x - R, b.y - R * 0.55, R * 2, R * 1.1);
          } else {
            ctx.fillStyle = b.color || (b.cue ? '#ffffff' : '#e74c3c');
            ctx.fillRect(b.x - R, b.y - R, R * 2, R * 2);
          }

          // Number badge (if not cue ball)
          if (!b.cue && b.num !== undefined) {
            ctx.fillStyle = '#ffffff';
            ctx.beginPath();
            ctx.arc(b.x, b.y, R * 0.45, 0, Math.PI * 2);
            ctx.fill();

            ctx.fillStyle = '#111111';
            ctx.font = 'bold 8px sans-serif';
            ctx.textAlign = 'center';
            ctx.textBaseline = 'middle';
            ctx.fillText(b.num, b.x, b.y + 0.5);
          }

          // Cue ball red alignment dot
          if (b.cue) {
            ctx.fillStyle = '#e53e3e';
            ctx.beginPath();
            ctx.arc(b.x + 2, b.y - 2, 1.8, 0, Math.PI * 2);
            ctx.fill();
          }

          // 3D Specular Highlight overlay
          const highlight = ctx.createRadialGradient(
            b.x - R * 0.3, b.y - R * 0.3, R * 0.1,
            b.x, b.y, R
          );
          highlight.addColorStop(0, 'rgba(255, 255, 255, 0.55)');
          highlight.addColorStop(0.5, 'rgba(255, 255, 255, 0.05)');
          highlight.addColorStop(1, 'rgba(0, 0, 0, 0.35)');

          ctx.fillStyle = highlight;
          ctx.fillRect(b.x - R, b.y - R, R * 2, R * 2);
          ctx.restore();
        }

        // 5. Aim Line & Cue Stick while dragging
        if (isDragging) {
          const cb = simBalls.find(b => b.cue);
          if (cb && !cb.potted) {
            const dx = cb.x - dragPos.x;
            const dy = cb.y - dragPos.y;
            const dist = Math.hypot(dx, dy);

            if (dist > 5) {
              const ux = dx / dist;
              const uy = dy / dist;

              // Raycast aim line forward to nearest obstacle / cushion
              let tHit = 1000;

              // Cushion bounds check
              if (ux < 0) tHit = Math.min(tHit, (R - cb.x) / ux);
              if (ux > 0) tHit = Math.min(tHit, ((W - R) - cb.x) / ux);
              if (uy < 0) tHit = Math.min(tHit, (R - cb.y) / uy);
              if (uy > 0) tHit = Math.min(tHit, ((H - R) - cb.y) / uy);

              let hitBall = null;
              for (let other of simBalls) {
                if (other.potted || other.cue) continue;
                const ox = other.x - cb.x;
                const oy = other.y - cb.y;
                const proj = ox * ux + oy * uy;
                if (proj > 0) {
                  const perpSq = (ox * ox + oy * oy) - proj * proj;
                  if (perpSq < (2 * R) * (2 * R)) {
                    const d = proj - Math.sqrt((2 * R) * (2 * R) - perpSq);
                    if (d > 0 && d < tHit) {
                      tHit = d;
                      hitBall = other;
                    }
                  }
                }
              }

              const hitX = cb.x + ux * tHit;
              const hitY = cb.y + uy * tHit;

              // Trajectory Line
              ctx.strokeStyle = 'rgba(255, 255, 255, 0.7)';
              ctx.lineWidth = 1.5;
              ctx.setLineDash([5, 5]);
              ctx.beginPath();
              ctx.moveTo(cb.x, cb.y);
              ctx.lineTo(hitX, hitY);
              ctx.stroke();
              ctx.setLineDash([]);

              // Ghost Cue Ball at impact point
              ctx.strokeStyle = 'rgba(255, 255, 255, 0.8)';
              ctx.lineWidth = 1;
              ctx.beginPath();
              ctx.arc(hitX, hitY, R, 0, Math.PI * 2);
              ctx.stroke();

              if (hitBall) {
                // Target ball deflection prediction vector
                const tx = hitBall.x - hitX;
                const ty = hitBall.y - hitY;
                const tLen = Math.hypot(tx, ty);
                if (tLen > 0) {
                  ctx.strokeStyle = 'rgba(80, 227, 194, 0.8)';
                  ctx.beginPath();
                  ctx.moveTo(hitBall.x, hitBall.y);
                  ctx.lineTo(hitBall.x + (tx / tLen) * 40, hitBall.y + (ty / tLen) * 40);
                  ctx.stroke();
                }
              }

              // Render Cue Stick behind ball
              const pullBack = Math.min(160, dist);
              const stickLength = 220;
              const stickStart = R + 8 + pullBack;
              const stickEnd = stickStart + stickLength;

              const x1 = cb.x - ux * stickStart;
              const y1 = cb.y - uy * stickStart;
              const x2 = cb.x - ux * stickEnd;
              const y2 = cb.y - uy * stickEnd;

              const stickGrad = ctx.createLinearGradient(x1, y1, x2, y2);
              stickGrad.addColorStop(0, '#f6e05e');
              stickGrad.addColorStop(0.2, '#d69e2e');
              stickGrad.addColorStop(1, '#4a5568');

              ctx.strokeStyle = stickGrad;
              ctx.lineWidth = 6;
              ctx.lineCap = 'round';
              ctx.beginPath();
              ctx.moveTo(x1, y1);
              ctx.lineTo(x2, y2);
              ctx.stroke();

              // Power indicator text / bar
              const powerPct = Math.min(100, Math.round((dist / 200) * 100));
              ctx.fillStyle = '#ffffff';
              ctx.font = 'bold 12px sans-serif';
              ctx.textAlign = 'center';
              ctx.fillText(`Power: ${powerPct}%`, cb.x, cb.y - R - 14);
            }
          }
        }
      }

      // Mouse / Pointer Interaction handlers
      canvas.addEventListener('pointerdown', (e) => {
        const rect = canvas.getBoundingClientRect();
        const mx = (e.clientX - rect.left) * (canvas.width / rect.width);
        const my = (e.clientY - rect.top) * (canvas.height / rect.height);

        let cb = simBalls.find(b => b.cue);
        if (!cb) return;

        if (cb.potted) {
          // Re-place cue ball if potted
          cb.potted = false;
          cb.x = Math.max(R, Math.min(W - R, mx));
          cb.y = Math.max(R, Math.min(H - R, my));
          cb.vx = 0;
          cb.vy = 0;
          redraw();
          return;
        }

        // Allow shooting if cue ball speed is nearly zero
        const isStationary = Math.hypot(cb.vx, cb.vy) < 10;
        const dist = Math.hypot(mx - cb.x, my - cb.y);

        if (isStationary && (dist < 80 || true)) {
          isDragging = true;
          dragPos = { x: mx, y: my };
          try { canvas.setPointerCapture(e.pointerId); } catch (err) {}
          redraw();
        }
      });

      canvas.addEventListener('pointermove', (e) => {
        if (!isDragging) return;
        const rect = canvas.getBoundingClientRect();
        dragPos.x = (e.clientX - rect.left) * (canvas.width / rect.width);
        dragPos.y = (e.clientY - rect.top) * (canvas.height / rect.height);
        redraw();
      });

      function handlePointerUp(e) {
        if (!isDragging) return;
        isDragging = false;
        try { canvas.releasePointerCapture(e.pointerId); } catch (err) {}

        const cb = simBalls.find(b => b.cue);
        if (!cb || cb.potted) {
          redraw();
          return;
        }

        const dx = cb.x - dragPos.x;
        const dy = cb.y - dragPos.y;
        const dist = Math.hypot(dx, dy);

        if (dist > 5) {
          const powerScale = 7.5;
          let vx = dx * powerScale;
          let vy = dy * powerScale;

          const speed = Math.hypot(vx, vy);
          const maxSpeed = 2200;
          if (speed > maxSpeed) {
            vx = (vx / speed) * maxSpeed;
            vy = (vy / speed) * maxSpeed;
          }

          window.sim.shoot(vx, vy);
        } else {
          redraw();
        }
      }

      canvas.addEventListener('pointerup', handlePointerUp);
      canvas.addEventListener('pointercancel', handlePointerUp);

      rackBtn.addEventListener('click', () => {
        window.sim.reset();
      });

      // Initial Setup & Start Animation Loop
      window.sim.reset();
      window.sim.resume();

    })();
  </script>
</body>
</html>
